// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an address for the adversarial callee (we will deploy it and pass its address),
    // a uint256 v, and a bytes32 seed to fuzz _tos contents length and members
    function testFuzz_property(uint256 v, uint8 tosLen, bytes32 seed) public {
        // keep tosLen in a reasonable wide bound but allow 1..10
        tosLen = uint8(bound(tosLen, 1, 10)); // require non-empty per contract

        // Deploy a helper callee that implements only transferFrom and reverts on transfer
        OnlyTransferFromOnlyRevertOnTransfer callee = new OnlyTransferFromOnlyRevertOnTransfer();

        // prepare _tos array with distinct addresses derived from seed
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            // derive an address from seed and index to vary inputs
            bytes32 h = keccak256(abi.encodePacked(seed, i));
            tos[i] = address(uint160(uint256(h)));
        }

        // Call c.transfer with 'from' set to address(0x123) (fuzzers can't deploy arbitrary code at fuzzed addresses,
        // but the important part is the callee behavior), pass the callee address we control
        bool ok;
        try c.transfer(address(0x123), address(callee), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // General invariant: the reference implementation always succeeds (does not revert) when the callee implements transferFrom.
        // We assert that c.transfer call did not revert. This holds for the reference but the mutant (which calls transfer(...))
        // will revert for our helper callee because it explicitly reverts on transfer.
        assertTrue(ok);
    }
}

// Adversarial helper: implements transferFrom (succeeds) but reverts on transfer
contract OnlyTransferFromOnlyRevertOnTransfer {
    // mimic ERC20-like transferFrom signature
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
    // different selector: transfer(address,address,uint256) -> revert to distinguish behavior
    function transfer(address, address, uint256) external pure returns (bool) {
        revert("transfer not supported");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: from address (actor) and an uint value; we also fuzz the array length via a bool
    function testFuzz_property(address from, uint256 v, bool includeTarget) public {
        // keep 'from' non-zero to be a meaningful actor
        vm.assume(from != address(0));

        // deploy a helper that will ALWAYS revert on any call
        Reverter reverter = new Reverter();

        // build _tos array: either include one target (the reverter) or be empty; require non-empty per contract
        address[] memory tos;
        if (includeTarget) {
            tos = new address[](1);
            tos[0] = address(reverter);
        } else {
            // if empty, should be rejected by require(_tos.length > 0) in both versions
            tos = new address[](0);
        }

        // Call c.transfer via try/catch to observe whether it reverts or not.
        bool ok;
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE ASSERTION (single assert):
        // If tos is non-empty and contains a callee that reverts, the correct contract MUST revert (ok == false).
        // For empty tos the contract must revert due to require(_tos.length > 0) as well.
        // Thus, we assert that ok == false for our constructed inputs when tos is non-empty (includeTarget==true)
        // and also when tos is empty (the require).
        if (includeTarget) {
            // when we included the reverter, the reference should revert; the mutant (which ignores failures)
            // would return true, so this assertion will fail on the mutant for some fuzzed inputs
            assertTrue(ok == false);
        } else {
            // when tos is empty the require should cause revert as well
            assertTrue(ok == false);
        }
    }
}

contract Reverter {
    fallback() external payable { revert("revert"); }
}
